package com.nimbusbill.customer.repository;import com.nimbusbill.customer.entity.NotificationOutbox;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.Instant;import java.util.*;public interface NotificationOutboxRepository extends JpaRepository<NotificationOutbox,UUID>{@Query("select n from NotificationOutbox n where n.status in :statuses and (n.nextAttemptAt is null or n.nextAttemptAt<=:now) order by n.createdAt") List<NotificationOutbox> ready(@Param("statuses") List<String> statuses,@Param("now") Instant now,org.springframework.data.domain.Pageable page);}
